  const hall = (x, y, w = 150, h = 90, [fill, stroke] = OLD) => {
    const cols = 4, gap = (w - 30) / (cols - 1);
    let o = `<path d="M${f(x - w / 2 - 10)} ${f(y - h)} L${f(x)} ${f(y - h - 36)} L${f(x + w / 2 + 10)} ${f(y - h)} Z" fill="${fill}" stroke="${stroke}" stroke-width="3" stroke-linejoin="round"/>`;
    o += `<rect x="${f(x - w / 2)}" y="${f(y - h)}" width="${w}" height="${h}" fill="white" stroke="${stroke}" stroke-width="3"/>`;
    for (let i = 0; i < cols; i++) o += `<rect x="${f(x - w / 2 + 9 + i * gap)}" y="${f(y - h + 10)}" width="12" height="${h - 20}" fill="${fill}"/>`;
    return o;
  };

  // 장면마다 같이 쓰는 움직임
  const base = (id) => {
    let s = `
    .sc-${id} .pop, .sc-${id} .pulse, .sc-${id} .ring, .sc-${id} .twk { transform-box: fill-box; transform-origin: center; }
    .sc-${id} .twk { animation: ${id}-twk 1.6s ease-in-out infinite alternate; }
    .sc-${id} .mar { animation: ${id}-mar .7s linear infinite; }
    .sc-${id} .draw { stroke-dasharray: 1; stroke-dashoffset: 1; transition: stroke-dashoffset 1.4s ease-in-out .2s; }
    .sc-${id} .grow { transform-box: fill-box; transform-origin: 0 50%; transform: scaleX(0); transition: transform 1.2s ease-in-out .2s; }
    .sc-${id} .growy { transform-box: fill-box; transform-origin: 50% 100%; transform: scaleY(0); transition: transform 1s ease-out .2s; }
    .sc-${id} .mv { transform: translate(var(--x1), var(--y1)); transition: transform 1.4s ease-in-out, opacity .6s ease; }
    .sc-${id} .dim { transition: opacity .6s ease; }
    .sc-${id} .jig { animation: ${id}-jig 1.3s ease-in-out infinite; }
    .sc-${id} .bob { animation: ${id}-bob 1.4s ease-in-out infinite; }
    .sc-${id} .ring { opacity: 0; }
    @keyframes ${id}-pop { 0% { opacity: 0; transform: scale(.3); } 70% { opacity: 1; transform: scale(1.12); } 100% { opacity: 1; transform: scale(1); } }
    @keyframes ${id}-fin { from { opacity: 0; } to { opacity: 1; } }
    @keyframes ${id}-rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
    @keyframes ${id}-drop { from { opacity: 0; transform: translateY(-30px); } to { opacity: 1; transform: none; } }
    @keyframes ${id}-pulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.1); } }
    @keyframes ${id}-flash { 0% { opacity: 0; } 20% { opacity: 1; } 40% { opacity: .25; } 60% { opacity: 1; } 80% { opacity: .25; } 100% { opacity: 1; } }
    @keyframes ${id}-ring { 0% { opacity: .9; transform: scale(1); } 100% { opacity: 0; transform: scale(1.6); } }
    @keyframes ${id}-twk { from { opacity: .35; } to { opacity: 1; } }
    @keyframes ${id}-mar { from { stroke-dashoffset: 24; } to { stroke-dashoffset: 0; } }
    @keyframes ${id}-jig { 0%, 100% { transform: translate(0, 0); } 25% { transform: translate(3px, -2px); } 50% { transform: translate(-3px, 1.5px); } 75% { transform: translate(2px, 2.5px); } }
    @keyframes ${id}-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
    `;
    for (let n = 1; n <= 5; n++) s += `
    .on${n} .sc-${id} .pop${n} { animation: ${id}-pop .5s ease-out both; }
    .on${n} .sc-${id} .fin${n} { animation: ${id}-fin .5s ease-out both; }
    .on${n} .sc-${id} .rise${n} { animation: ${id}-rise .45s ease-out both; }
    .on${n} .sc-${id} .drop${n} { animation: ${id}-drop .5s ease-out both; }
    .on${n} .sc-${id} .pulse${n} { animation: ${id}-pulse .7s ease-in-out .3s 2; }
    .on${n} .sc-${id} .flash${n} { animation: ${id}-flash 1.4s ease-in-out both; }
    .on${n} .sc-${id} .ring${n} { animation: ${id}-ring 1.1s ease-out .3s 2; }
    .on${n} .sc-${id} .draw${n} { stroke-dashoffset: 0; }
    .on${n} .sc-${id} .grow${n}, .on${n} .sc-${id} .growy${n} { transform: none; }
    .on${n} .sc-${id} .dim${n} { opacity: .28; }`;
    for (let n = 2; n <= 5; n++) s += `
    .on${n} .sc-${id} .mv { transform: translate(var(--x${n}), var(--y${n})); }`;
    return s;
  };

  const GRAY = ['#f1f3f0', C.muted], PAPER = ['white', C.ink];
  const T = (x, y, inner, s = 1) => `<g transform="translate(${f(x)} ${f(y)})${s !== 1 ? ` scale(${s})` : ''}">${inner}</g>`;
  const crown = (x, y, s = 1) => `<path d="M${f(x - 10 * s)} ${f(y)} L${f(x - 10 * s)} ${f(y - 10 * s)} L${f(x - 5 * s)} ${f(y - 5 * s)} L${f(x)} ${f(y - 12 * s)} L${f(x + 5 * s)} ${f(y - 5 * s)} L${f(x + 10 * s)} ${f(y - 10 * s)} L${f(x + 10 * s)} ${f(y)} Z" fill="${C.yellow}" stroke="${C.orange}" stroke-width="2" stroke-linejoin="round"/>`;

  // ══════════════ 지도 ══════════════
  // 오늘날 땅·바다 모양 위에 옛 문명·나라 범위를 대략 칠한다. 나라 경계선은 긋지 않는다(오늘날 국경을 옛 국경처럼 보이지 않게).
  const R = Math.PI / 180;
  const decR = (s) => { const v = s.split(',').map(Number), p = []; let x = 0, y = 0; for (let i = 0; i + 1 < v.length; i += 2) { x += v[i]; y += v[i + 1]; p.push([x / 10, y / 10]); } return p; };
  const RINGS = LANDS.split('|').map(decR);
  const Yk = (la) => Math.log(Math.tan(Math.PI / 4 + (la * R) / 2));
  // 메르카토르: 경도 lo0~lo1 이 화면 가로 640, 위도 latTop 이 맨 위
  const view = (lo0, lo1, latTop) => { const s = 640 / ((lo1 - lo0) * R), y0 = Yk(latTop); return { pt: (lo, la) => [(lo - lo0) * R * s, (y0 - Yk(la)) * s] }; };
  const ptsI = (pts) => { let d = '', px = 1e9, py = 1e9; for (const [x, y] of pts) { const X = Math.round(x), Y = Math.round(y); if (X === px && Y === py) continue; d += (d ? 'L' : 'M') + X + ' ' + Y; px = X; py = Y; } return d; };
  const lineD = (v, ll) => 'M' + ll.map(([lo, la]) => { const [x, y] = v.pt(lo, la); return `${f(x)} ${f(y)}`; }).join(' L');
  const polyD = (v, ll) => lineD(v, ll) + 'Z';
  const landCache = new Map();
  // 화면 밖으로 20 넘게 나간 부분은 잘라 낸다(사각형 자르기)
  const clipBox = (pts) => {
    let out = pts;
    const E = [[(p) => p[0] >= -20, 0, -20], [(p) => p[0] <= 660, 0, 660], [(p) => p[1] >= -20, 1, -20], [(p) => p[1] <= 380, 1, 380]];
    for (const [inside, k, v] of E) {
      const inp = out; out = [];
      for (let i = 0; i < inp.length; i++) {
        const a = inp[(i + inp.length - 1) % inp.length], b = inp[i];
        const cut = () => { const t = (v - a[k]) / (b[k] - a[k]); return k ? [a[0] + t * (b[0] - a[0]), v] : [v, a[1] + t * (b[1] - a[1])]; };
        if (inside(b)) { if (!inside(a)) out.push(cut()); out.push(b); } else if (inside(a)) out.push(cut());
      }
      if (!out.length) break;
    }
    return out;
  };
  const landD = (v) => {
    if (!landCache.has(v)) landCache.set(v, RINGS.map((r) => clipBox(r.map(([lo, la]) => v.pt(lo, la)))).filter((r) => r.length > 2).map((r) => ptsI(r) + 'Z').join(''));
    return landCache.get(v);
  };
  // 바다 + 땅(민트 위에 초록을 옅게 한 겹) + 땅 모양 잘라 내기 틀
  const mapBase = (id, v) => `<defs><path id="${id}-L" d="${landD(v)}"/><clipPath id="${id}-c"><use href="#${id}-L"/></clipPath></defs><rect width="640" height="360" fill="${C.sky}"/><use href="#${id}-L" fill="${C.mint}"/><use href="#${id}-L" fill="${C.green}" fill-opacity=".16"/>`;
  // 땅 위에만 칠하는 범위
  const area = (id, v, ll, fill, op = 0.55, extra = '') => `<path d="${polyD(v, ll)}" fill="${fill}" fill-opacity="${op}" clip-path="url(#${id}-c)"${extra}/>`;
  const areaEdge = (id, v, ll, color, w = 3) => `<path d="${polyD(v, ll)}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linejoin="round" clip-path="url(#${id}-c)"/>`;
  const river = (v, name, { w = 2.2, color = C.blue, cls = '', op = 0.8 } = {}) => `<path class="${cls}"${cls.includes('draw') ? ' pathLength="1"' : ''} d="${lineD(v, decR(RIV[name]))}" stroke="${color}" stroke-width="${w}" stroke-opacity="${op}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;
  // 지도 위 글씨: 바탕색 테두리로 또렷하게
  const lab = (x, y, s, { size = 18, color = C.ink, anchor = 'middle' } = {}) =>
    `<text x="${f(x)}" y="${f(y)}" text-anchor="${anchor}" font-size="${size}" font-weight="700" fill="${color}" stroke="${C.paper}" stroke-width="5" stroke-linejoin="round" paint-order="stroke">${s}</text>`;
  const dot = (x, y, color = C.orange, r = 6) => `<circle cx="${f(x)}" cy="${f(y)}" r="${r}" fill="${color}" stroke="white" stroke-width="2.5"/>`;
  // 작은 그림(밑 가운데 x, y)
  const ziggurat = (x, y) => `<path d="M${x - 24} ${y} h48 v-10 h-8 v-10 h-8 v-10 h-16 v10 h-8 v10 h-8 Z" fill="${C.peach}" stroke="${C.orange}" stroke-width="2.5" stroke-linejoin="round"/>`;
  const pyramid = (x, y) => `<path d="M${x - 26} ${y} L${x} ${y - 30} L${x + 26} ${y} Z" fill="${C.yellow}" stroke="${C.orange}" stroke-width="2.5" stroke-linejoin="round"/><path d="M${x} ${y - 30} L${x + 6} ${y}" stroke="${C.orange}" stroke-width="2"/>`;
  const bricks = (x, y) => { let o = `<rect x="${x - 24}" y="${y - 28}" width="48" height="28" fill="${C.peach}" stroke="${C.orange}" stroke-width="2.5"/>`; o += `<path d="M${x - 24} ${y - 14} h48 M${x - 8} ${y - 28} v14 M${x + 8} ${y - 28} v14 M${x - 16} ${y - 14} v14 M${x} ${y - 14} v14 M${x + 16} ${y - 14} v14" stroke="${C.orange}" stroke-width="2"/>`; return o; };
  const ding = (x, y) => `<path d="M${x - 20} ${y - 26} H${x + 20} Q${x + 18} ${y - 6} ${x} ${y - 6} Q${x - 18} ${y - 6} ${x - 20} ${y - 26} Z" fill="${C.green}" fill-opacity=".55" stroke="${C.green}" stroke-width="2.5"/><path d="M${x - 12} ${y - 8} L${x - 15} ${y} M${x + 12} ${y - 8} L${x + 15} ${y} M${x} ${y - 6} V${y} M${x - 12} ${y - 26} V${y - 33} M${x + 12} ${y - 26} V${y - 33}" stroke="${C.green}" stroke-width="3" stroke-linecap="round"/>`;

  // ════ 2 문명의 발생 — 네 큰 강 유역(같은 지도를 다섯 낱말이 나누어 쓴다) ════
  const V1 = view(22, 124, 46);
  const CIV = {
    meso: { ll: [[38.5, 36.9], [42, 37.6], [45, 36.3], [47.6, 33.2], [48.6, 30.6], [47.6, 29.6], [46, 30.4], [44, 32], [41.6, 34], [39.2, 35.4]], rivers: ['티그리스강', '유프라테스강'] },
    egypt: { ll: [[29.4, 31.4], [32.6, 31.6], [31.9, 29.6], [31.6, 27.2], [33.1, 25.5], [33.3, 23.8], [32.5, 23.8], [31.2, 26.4], [30.5, 28.5], [30.0, 30.2]], rivers: ['나일강'] },
    indus: { ll: [[66.6, 24.6], [68.6, 23.6], [70.6, 25.9], [72.2, 28.4], [74.6, 30.4], [75.6, 32.4], [73.2, 33.6], [71, 31.2], [69, 28.6], [67.4, 26.6]], rivers: ['인더스강'] },
    china: { ll: [[106, 34.1], [109, 33.7], [113, 33.9], [116.2, 34.2], [118.8, 36.4], [117.6, 38.6], [114, 37.7], [111.4, 36.3], [109, 35.6], [106.4, 35.6]], rivers: ['황허'] }
  };
  const ALLRIV = ['티그리스강', '유프라테스강', '나일강', '인더스강', '황허'];
  const P1 = (lo, la) => V1.pt(lo, la);
  // 한 문명 낱말: 1칸은 네 강이 다 보이는 지도, 2칸부터 그 강 유역으로 다가간다(지도 묶음을 transform 으로 키운다)
  const ns = ' vector-effect="non-scaling-stroke"';
  const civFig = (key, word, id, o) => {
    let css = base(id);
    const c = CIV[key], k = o.k, [cx, cy] = P1(...o.center);
    const cl = (v, a, b) => Math.min(b, Math.max(a, v));
    const tx = cl(320 - k * cx, 640 - 640 * k, 0), ty = cl(175 - k * cy, 360 - 360 * k, 0);
    const Z = (lo, la) => { const [x, y] = P1(lo, la); return [tx + k * x, ty + k * y]; };
    css += `.sc-${id} .zoom { transition: transform 1.4s ease-in-out .1s; } .on2 .sc-${id} .zoom { transform: matrix(${k}, 0, 0, ${k}, ${f(tx)}, ${f(ty)}); }`;
    let map = mapBase(id, V1);
    map += ALLRIV.filter((r) => !c.rivers.includes(r)).map((r) => river(V1, r, { op: 0.55 }).replace('<path ', `<path${ns} `)).join('');
    // 1칸: 강이 흐른다(물줄기가 하류 쪽으로 그려진다) — 2칸부터는 굵기가 그대로인 같은 강으로 바꾼다
    c.rivers.forEach((r, i) => {
      map += `<g class="b1 h2">${river(V1, r, { w: 5, cls: 'draw draw1', op: 1 }).replace('<path ', `<path style="transition-delay:${0.2 + i * 0.3}s" `)}</g>`;
    });
    // 2칸: 문명이 일어난 땅(강은 그 위에 다시)
    map += at(2, 'fin', area(id, V1, c.ll, C.orange, 0.6) + `<path d="${polyD(V1, c.ll)}" fill="none" stroke="${C.orange}" stroke-width="2.5"${ns} clip-path="url(#${id}-c)"/>`, 0.9);
    c.rivers.forEach((r) => { map += `<g class="b2">${river(V1, r, { w: 5, op: 1 }).replace('<path ', `<path${ns} `)}</g>`; });
    map += `<g class="b3"><path class="flash flash3" d="${polyD(V1, c.ll)}" fill="none" stroke="${C.red}" stroke-width="4"${ns} stroke-linejoin="round" clip-path="url(#${id}-c)"/></g>`;
    let body = `<g class="zoom">${map}</g>`;
    o.riv1.forEach(([s, lo, la, anchor], i) => { const [x, y] = P1(lo, la); body += `<g class="b1 h2">${g('fin fin1', lab(x, y, s, { size: 19, color: C.blue, anchor }), 1.0 + i * 0.2)}</g>`; });
    o.riv2.forEach(([s, lo, la, anchor], i) => { const [x, y] = Z(lo, la); body += at(2, 'fin', lab(x, y, s, { size: 20, color: C.blue, anchor }), 1.4 + i * 0.1); });
    const [zx, zy] = Z(...o.center);
    body += ring(f(zx), f(zy), 50, 2, C.orange, 1.0);
    o.cities.forEach(([s, lo, la, dx, dy, anchor], i) => { const [x, y] = Z(lo, la); body += at(2, 'pop', dot(x, y, C.red, 6) + lab(x + dx, y + dy, s, { size: 19, anchor }), 1.3 + i * 0.15); });
    body += at(2, 'pop', tag(o.year[0], o.year[1], o.year[2], HOT, { size: 20 }), 1.6);
    // 3칸: 그 문명의 상징과 이름
    const [ix, iy] = Z(o.icon[1], o.icon[2]);
    body += at(3, 'pop', o.icon[0](Math.round(ix), Math.round(iy)) + (o.icon[3] ? lab(ix, iy + 24, o.icon[3], { size: 18 }) : ''), 0.1);
    body += at(3, 'pop', tag(o.name[0], o.name[1], word, HOT, { size: 24 }), 0.5);
    put(KEY('2', word), svg(id, body, css));
  };
  civFig('meso', '메소포타미아 문명', 't81-h2-meso', {
    k: 2.6, center: [44.5, 33.5],
    riv1: [['티그리스강', 47.6, 36.2, 'start'], ['유프라테스강', 36, 30.4, 'middle']],
    riv2: [['티그리스강', 47.2, 35.4, 'start'], ['유프라테스강', 39.4, 34.2, 'end']],
    cities: [['우르', 46.1, 30.96, 12, 8, 'start']],
    year: [200, 280, '기원전 3500년경'],
    icon: [ziggurat, 51.6, 32.6, '지구라트'],
    name: [330, 328]
  });
  civFig('egypt', '이집트 문명', 't81-h2-egypt', {
    k: 3, center: [31.5, 27.5],
    riv1: [['나일강', 33.6, 21.6, 'start']],
    riv2: [['나일강', 33.2, 21.8, 'start']],
    cities: [['멤피스', 31.25, 29.85, 12, 7, 'start']],
    year: [420, 150, '기원전 3000년경'],
    icon: [pyramid, 28.6, 28.4, '피라미드'],
    name: [360, 328]
  });
  civFig('indus', '인도 문명', 't81-h2-indus', {
    k: 2.4, center: [71, 29],
    riv1: [['인더스강', 76.2, 34.6, 'start']],
    riv2: [['인더스강', 76.4, 34.2, 'start']],
    cities: [['하라파', 72.86, 30.63, 12, 8, 'start'], ['모헨조다로', 68.14, 27.33, -12, 7, 'end']],
    year: [180, 290, '기원전 2500년경'],
    icon: [bricks, 75.6, 27.2, '벽돌 도시'],
    name: [420, 328]
  });
  civFig('china', '중국 문명', 't81-h2-china', {
    k: 2.4, center: [112, 36],
    riv1: [['황허', 107.2, 39.6, 'end']],
    riv2: [['황허', 104, 37.4, 'end']],
    cities: [['은허', 114.3, 36.1, 12, -8, 'start']],
    year: [300, 290, '기원전 2500년경'],
    icon: [ding, 110.8, 32, '청동기'],
    name: [470, 328]
  });

  // ── 문명: 네 큰 강 → 도시·문자·청동기·국가 ──
  (function () {
    const id = 't81-h2-munmyeong';
    let css = base(id), body = mapBase(id, V1);
    ALLRIV.forEach((r, i) => { body += `<g class="b1">${river(V1, r, { w: 4.5, cls: 'draw draw1', op: 1 }).replace('<path ', `<path style="transition-delay:${0.1 + i * 0.15}s" `)}</g>`; });
    body += `<g class="b1 h2">${g('pop pop1', tag(320, 316, '큰 강', COLD, { size: 20 }), 1.2)}</g>`;
    Object.values(CIV).forEach((c, i) => { body += at(2, 'fin', area(id, V1, c.ll, C.orange, 0.6) + areaEdge(id, V1, c.ll, C.orange, 2.5), 0.1 + i * 0.15); });
    body += shown(2, ALLRIV.map((r) => river(V1, r, { w: 4.5, op: 1 })).join(''));
    [[44.42, 32.54], [31.25, 29.85], [68.14, 27.33], [114.3, 36.1]].forEach(([lo, la], i) => { const [x, y] = P1(lo, la); body += at(2, 'pop', dot(x, y, C.red, 5), 0.4 + i * 0.15); });
    [['도시', 236], ['문자', 304], ['청동기', 386], ['국가', 468]].forEach(([w, x], i) => { body += at(2, 'pop', tag(x, 316, w, HOT, { size: 20 }), 0.9 + i * 0.25); });
    const NAMES = [['메소포타미아', 46.5, 41, 'start'], ['이집트', 31, 19.2, 'middle'], ['인도', 66, 31.8, 'end'], ['중국', 112, 41.4, 'middle']];
    NAMES.forEach(([s, lo, la, anchor], i) => { const [x, y] = P1(lo, la); body += at(3, 'pop', lab(x, y, s, { size: 19, color: C.red, anchor }), 0.2 + i * 0.2); });
    body += at(3, 'pop', tag(320, 262, '문명', HOT, { size: 26 }), 1.0);
    put(KEY('2', '문명'), svg(id, body, css));
  })();

  // ════ 아케메네스 왕조 · 헬레니즘: 지중해 동쪽 ~ 인더스강 ════
  const V2 = view(14, 82, 47);
  const P2 = (lo, la) => V2.pt(lo, la);
